		["Contribution from Main Hand:"] = "主手貢獻:",
		["Contribution from Non-crits:"] = "非暴擊貢獻:",
		["Contribution from Off Hand:"] = "副手貢獻:",
		["Control + click to open in web-browser"] = "Control + 點擊以在瀏覽器開啟",
		["Controls how ^xE05030life ^7regeneration is calculated:\n\\tMinimum: does not include burst regen\n\\tAverage: includes burst regen, averaged based on uptime\n\\tBurst: includes full burst regen"] = "控制^xE05030生命^7回復如何計算:\n\\t最小: 不包含爆發回復\n\\t平均: 包含爆發回復，依持續時間平均\n\\t爆發: 包含完整爆發回復",
		["Controls how Defending with Double Armour is calculated:\n\\tMinimum: never Defend with Double Armour\n\\tAverage: Damage Reduction from Defending with Double Armour is proportional to chance\n\\tMaximum: always Defend with Double Armour\nThis setting has no effect if you have 100% chance to Defend with Double Armour."] = "控制以雙倍護甲防禦如何計算:\n\\t最小: 永不以雙倍護甲防禦\n\\t平均: 以雙倍護甲防禦的傷害減免依機率比例計算\n\\t最大: 總是以雙倍護甲防禦\n若你有 100% 機率以雙倍護甲防禦，此設定無效。",
		["Controls how Empowered spells from Pacts are calculated:\nAverage: Averages the effect based on Pact uptime.\nMax Hit: Applies the full effect to one Empowered spell."] = "控制協議強化的法術如何計算:\n平均: 依協議持續時間平均效果。\n最大擊中: 對一次強化法術套用完整效果。",
		["Controls how exerted attacks from Warcries are calculated:\nAverage: Averages out Warcry usage with cast time, attack speed and warcry cooldown.\nMax Hit: Shows maximum hit for lining up all warcries."] = "控制戰吼激發的攻擊如何計算:\n平均: 依施放時間、攻擊速度與戰吼冷卻時間平均戰吼使用。\n最大擊中: 顯示所有戰吼疊加時的最大擊中。",
		["Controls how modifiers which choose a random element will function.\n\\tAverage: Modifiers will grant one third of their value to ^xB97123Fire^7, ^x3F6DB3Cold^7, and ^xADAA47Lightning ^7simultaneously\n\\t^xB97123Fire ^7/ ^x3F6DB3Cold ^7/ ^xADAA47Lightning^7: Modifiers will grant their full value as the specified element\nIf a modifier chooses between just two elements, the full value can only be given as those two elements."] = "控制選擇隨機元素的詞綴如何運作。\n\\t平均: 詞綴的三分之一數值同時給予^xB97123火焰^7、^x3F6DB3冰冷^7與^xADAA47閃電^7\n\\t^xB97123火焰 ^7/ ^x3F6DB3冰冷 ^7/ ^xADAA47閃電^7: 詞綴的完整數值給予指定元素\n若詞綴只在兩種元素間選擇，完整數值只能給予這兩種元素。",
		["Controls how resource on hit/kill is calculated:\n\\tMinimum: does not include chances\n\\tAverage: includes chance gains, averaged based on uptime\n\\tMaximum: treats all chances as certain"] = "控制擊中/擊殺時獲得資源如何計算:\n\\t最小: 不包含機率\n\\t平均: 包含機率獲得，依持續時間平均\n\\t最大: 所有機率視為必定發生",
		["Controls how the base damage for applying Ailments is calculated:\n\\tAverage: damage is based on the average application, including both crits and non-crits\n\\tCrits Only: damage is based solely on Ailments inflicted with crits"] = "控制施加異常狀態的基礎傷害如何計算:\n\\t平均: 依平均施加計算，包含暴擊與非暴擊\n\\t僅暴擊: 僅依暴擊施加的異常狀態計算",
		["Controls how the chance on hit to ignore enemy physical damage reduction is calculated:\n\\tMinimum: never ignores unless chance is at least 100%\n\\tAverage: damage is based on the average application\n\\tMax Effect: always ignores if you have any chance"] = "控制擊中時無視敵人物理傷害減免機率的計算方式:\n\\t最小: 除非機率至少 100%，否則從不無視\n\\t平均: 傷害依平均觸發計算\n\\t最大效果: 只要有機率就一律無視",
		["Controls how the hit/ailment effect of Ruthless Support is calculated:\n\\tAverage: damage is based on the average application\n\\tMax Effect: damage is based on maximum effect"] = "控制殘暴輔助的擊中/異常效果計算方式:\n\\t平均: 傷害依平均觸發計算\n\\t最大效果: 傷害依最大效果計算",
		["Controls which types of damage the EHP calculation uses:\n\\tAverage: uses the Average of all typed damage types (except Damage Over Time and Untyped)\n\nIf a specific damage type is selected, that will be the only type used."] = "控制 EHP 計算所使用的傷害類型:\n\\t平均: 使用所有類型傷害的平均值（不含持續傷害與無類型傷害）\n\n若選擇特定傷害類型，則只會使用該類型。",
