		["Importing..."] = "匯入中...",
		["In addition to allowing 'against Blinded Enemies' modifiers to apply,\n Blind applies the following effects.\n -20% Accuracy \n -20% ^x33FF77Evasion"] = "除了讓「對致盲敵人」詞綴生效外，\n 致盲還會套用以下效果。\n -20% 命中值 \n -20% ^x33FF77閃避",
		["In addition to allowing any 'against ^xADAA47Shocked ^7Enemies' modifiers to apply,\nthis will allow you to input the effect of the ^xADAA47Shock ^7applied to the enemy."] = "除了讓所有「對^xADAA47感電^7敵人」詞綴生效外，\n也讓你輸入施加於敵人的^xADAA47感電^7效果。",
		["In addition to allowing any 'while Elusive' modifiers to apply,\nthis will enable the Elusive buff itself:\n\\t15% Chance to Avoid all Damage from Hits\n\\t30% increased Movement Speed\nThe effect of Elusive decays over time."] = "除了讓所有「靈巧時」詞綴生效外，\n也會啟用靈巧增益本身:\n\\t15% 機率避免所有擊中傷害\n\\t增加 30% 移動速度\n靈巧的效果會隨時間衰減。",
		["In addition to allowing any 'while on Consecrated Ground' modifiers to apply,\nConsecrated Ground grants 5% ^xE05030Life ^7Regeneration to players and allies."] = "除了讓所有「在奉獻地面上時」詞綴生效外，\n奉獻地面還會給予玩家與友方 5% ^xE05030生命^7回復。",
		["In addition to allowing any 'while you have Arcane Surge' modifiers to apply,\nthis will enable the Arcane Surge buff itself. (Grants 20% increased cast speed and 30% increased Mana Regeneration rate)"] = "除了讓所有「當你有秘能波動時」詞綴生效外，\n也會啟用秘能波動增益本身。（增加 20% 施放速度與 30% 魔力回復速度）",
		["In addition to allowing any 'while you have Onslaught' modifiers to apply,\nthis will enable the Onslaught buff itself. (Grants 20% increased Attack, Cast, and Movement Speed)"] = "除了讓所有「當你有猛攻時」詞綴生效外，\n也會啟用猛攻增益本身。（增加 20% 攻擊、施放與移動速度）",
		["In addition to allowing any 'while you have Tailwind' modifiers to apply,\nthis will enable the Tailwind buff itself. (Grants 8% increased Action Speed)"] = "除了讓所有「當你有流順之風時」詞綴生效外，\n也會啟用流順之風增益本身。（增加 8% 行動速度）",
		["In addition to allowing any 'while your minions have Onslaught' modifiers to apply,\nthis will enable the Onslaught buff itself. (Grants 20% increased Attack, Cast, and Movement Speed)"] = "除了讓所有「當你的召喚物有猛攻時」詞綴生效外，\n也會啟用猛攻增益本身。（增加 20% 攻擊、施放與移動速度）",
