		["Sets current number of Bleeds on the enemy if using the Crimson Dance keystone.\nThis also implies that the enemy is Bleeding."] = "若使用緋紅舞蹈核心天賦，設定敵人身上目前的流血數。\n這也代表敵人正在流血。",
