		["Sets the blade count for Blade Vortex skills used by spectres.\nDefault is 1; maximum is 5."] = "設定幽魂使用的飛刃風暴技能的飛刃數。\n預設為 1；最大為 5。",
		["Sets the EHP calc to not apply gain on block, suppress or Defiance of Destiny effects"] = "讓 EHP 計算不套用格擋、抑制或拒絕命運的獲得效果",
		["Sets the EHP calc to pretend its unlucky and reduce the effects of random events such as\n\\tBlock/Spell Block Chance\n\\tDodge/Spell Dodge Chance\n\\tSpell Suppression Chance\n\\tAvoidance Chance"] = "讓 EHP 計算假設為不幸，降低以下隨機事件的效果\n\\t格擋/法術格擋機率\n\\t閃躲/法術閃躲機率\n\\t法術抑制機率\n\\t迴避機率",
		["Sets the level of Assassin's Mark to apply to the player."] = "設定套用於玩家的刺客印記等級。",
		["Sets the level of Conductivity to apply to the player."] = "設定套用於玩家的導電等級。",
		["Sets the level of Despair to apply to the player."] = "設定套用於玩家的絕望等級。",
