		["Sets the level of Enfeeble to apply to the player.\nIn mid tier maps, 'of Enfeeblement' applies level 10.\nIn high tier maps, 'of Enfeeblement' applies level 15."] = "設定套用於玩家的衰弱等級。\n中階地圖中，「衰弱之」套用等級 10。\n高階地圖中，「衰弱之」套用等級 15。",
