		["The amount of valour consumed for the placed banner"] = "插下旗幟所消耗的勇氣數量",
		["The build you are trying to load uses an unrecognised version of the passive skill tree.\nYou may need to update the program before loading this build."] = "你嘗試載入的 Build 使用了無法辨識的天賦樹版本。\n你可能需要先更新程式才能載入此 Build。",
		["The default value is "] = "預設值為 ",
		["The enemy will automatically be considered to be Cursed if you have at least one curse enabled,\nbut you can use this option to force it if necessary."] = "若你至少啟用一個詛咒，敵人將自動視為被詛咒，\n但你可以用此選項強制啟用。",
		["The enemy will automatically be considered to be Unique if they are a Boss,\nbut you can use this option to force it if necessary."] = "若敵人是頭目，會自動被視為傳奇，\n但必要時你可用此選項強制設定。",
		["The folder is not empty."] = "資料夾不是空的。",
		["The folder is not empty.\nAre you sure you want to delete folder:"] = "資料夾不是空的。\n確定要刪除資料夾:",
		["The item is invalid."] = "物品無效。",
		["The magnitude of Hallowing Flame stacks applied to the enemy"] = "施加於敵人的聖焰層數強度",
		["The percentage of the roll range the enemy hits for \n eg at 100% the enemy deals its maximum damage"] = "敵人擊中時的數值範圍百分比 \n 例如在 100% 時敵人造成最大傷害",
		["The socket must be allocated on your current tree; if it isn't, the jewel is only added to your item list."] = "插槽必須在目前天賦樹上已配置；否則珠寶只會加入你的物品清單。",
		["The trade site will filter out listings with other currencies,\nif anything other than \"Chaos Orb Equivalent\" is chosen and a maximum is specified."] = "若選擇「混沌石等值」以外的選項並設定上限，\n交易網站會過濾掉以其他通貨標價的物品。",
		["The tree has been converted to "] = "天賦樹已轉換為 ",
		["The URL is also copied to the clipboard."] = "網址也已複製到剪貼簿。",
		["This also implies that the enemy is ^xADAA47Brittle."] = "這也代表敵人處於^xADAA47易碎。",
		["This also implies that the enemy is ^xADAA47Sapped."] = "這也代表敵人處於^xADAA47削弱狀態。",
		["This also implies that the enemy is ^xADAA47Shocked."] = "這也代表敵人處於^xADAA47感電狀態。",
		["This also implies that the enemy is ^xB97123Burning."] = "這也代表敵人正在^xB97123燃燒。",
		["This also implies that the enemy is ^xB97123Scorched."] = "這也代表敵人被^xB97123焦灼。",
		["This also implies that you are ^x3F6DB3Chilled."] = "這也代表你被^x3F6DB3冰緩。",
		["This also implies that you are ^xADAA47Shocked."] = "這也代表你被^xADAA47感電。",
		["This also implies that you are ^xB97123Burning."] = "這也代表你正在^xB97123燃燒。",
		["This also implies that you are channelling"] = "這也代表你正在引導",
		["This also implies that you are Poisoned."] = "這也代表你處於中毒狀態。",
		["This also implies that you have a Totem summoned.\nThis will affect all 'per Summoned Totem' modifiers, even for non-Totem skills."] = "這也代表你有召喚圖騰。\n會影響所有「每個召喚的圖騰」詞綴，即使是非圖騰技能。",
		["This also implies that you have been Hit Recently."] = "這也代表你近期被擊中。",
		["This also implies that you have Blocked Recently."] = "這也代表你近期有格擋。",
		["This also implies that you have Hit Recently."] = "這也代表你近期有擊中。",
		["This also implies that you have killed and taunted recently."] = "這也代表你近期有擊殺並嘲諷。",
		["This also implies that you have Killed Recently."] = "這也代表你近期有擊殺。",
		["This also implies that you have Suppressed Recently."] = "這也代表你近期有壓抑。",
		["This also implies that you have used a Skill Recently."] = "這也代表你近期使用過技能。",
		["This also implies that you have used a Skill Recently.\nYou will automatically be considered to have Attacked Recently if your main skill is an attack,\nbut you can use this option to force it if necessary."] = "這也代表你近期使用過技能。\n若你的主要技能為攻擊，將自動視為近期攻擊過，\n但你可以用此選項強制啟用。",
		["This also implies that you have used a Skill Recently.\nYou will automatically be considered to have Cast a Spell Recently if your main skill is a spell,\nbut you can use this option to force it if necessary."] = "這也代表你近期使用過技能。\n若你的主要技能為法術，將自動視為近期施放過法術，\n但你可以用此選項強制啟用。",
		["This also implies that you have used a Skill Recently.\nYou will automatically be considered to have used a Minion skill Recently if your main skill is a Minion skill,\nbut you can use this option to force it if necessary."] = "這也代表你近期使用過技能。\n若你的主要技能為召喚物技能，將自動視為近期使用過召喚物技能，\n但你可以用此選項強制啟用。",
		["This also implies that you have used a Skill Recently.\nYou will automatically be considered to have used a Movement skill Recently if your main skill is a movement skill,\nbut you can use this option to force it if necessary."] = "這也代表你近期使用過技能。\n若你的主要技能為位移技能，將自動視為近期使用過位移技能，\n但你可以用此選項強制啟用。",
		["This also implies that you have used a Skill Recently.\nYou will automatically be considered to have used a Vaal skill Recently if your main skill is a Vaal skill,\nbut you can use this option to force it if necessary."] = "這也代表你近期使用過技能。\n若你的主要技能為瓦爾技能，將自動視為近期使用過瓦爾技能，\n但你可以用此選項強制啟用。",
		["This also implies that you have used a Skill Recently.."] = "這也代表你近期使用過技能。",
		["This also implies that you Totems have Hit Recently."] = "這也代表你的圖騰近期有擊中。",
		["This also implies that your Minions have Killed Recently."] = "這也代表你的召喚物近期有擊殺。",
		["This also implies that your Skills have Crit Recently."] = "這也代表你的技能近期有暴擊。",
		["This also implies that your Totems have Killed Recently."] = "這也代表你的圖騰近期有擊殺。",
		["This also implies you have 'Consumed a corpse Recently'"] = "這也代表你「近期吞噬過屍體」",
		["This also implies you have 'Used a Warcry Recently', 'Used a Warcry in the past 8 seconds', and 'Used a Skill Recently'"] = "這也代表你「近期使用過戰吼」、「過去 8 秒內使用過戰吼」以及「近期使用過技能」",
		["This applies -10% ^x3F6DB3Cold Resistance ^7to the enemy."] = "對敵人施加 -10% ^x3F6DB3冰冷抗性 ^7。",
		["This applies -10% ^xADAA47Lightning Resistance ^7to the enemy."] = "對敵人施加 -10% ^xADAA47閃電抗性 ^7。",
		["This applies -10% ^xB97123Fire Resistance ^7to the enemy."] = "對敵人施加 -10% ^xB97123火焰抗性 ^7。",
		["This build has unsaved changes.\nDo you want to save them "] = "此配置有未儲存的變更。\n是否要 ",
		["This can be useful if you're never going to path towards those excluded nodes and don't care what happens to them."] = "若你永遠不會連往那些被排除的節點，也不在乎它們變成什麼，這會很有用。",
		["This cannot be undone."] = "此操作無法復原。",
		["This config option is conditional with missing source and is invalid."] = "此設定選項為條件式但缺少來源，因此無效。",
		["This contains a list of your desired nodes along with their primary, secondary, and minimum weights."] = "這包含你所需節點的清單，以及其主要、次要與最低權重。",
		["This contains a list of your fallback nodes along with their primary, secondary, and minimum weights."] = "這包含你備援節點的清單，以及其主要、次要與最低權重。",
		["This controls the maximum amount of points that need to be spent to grab a node before its filtered out"] = "控制取得節點所需花費的最大點數，超過即被篩除",
		["This effect will only be applied while you can inflict ^x3F6DB3Brittle."] = "僅在你能施加^x3F6DB3易碎時套用此效果。",
		["This effect will only be applied while you can inflict ^xB97123Scorched."] = "僅在你能施加^xB97123焦灼時套用此效果。",
		["This enables the conditional culling strike from the mace mastery."] = "啟用錘專精的條件式撲殺。",
		["This is a hybrid node containing all additions to "] = "這是混合節點，包含所有以下的加成: ",
		["This is a list of item sets that will be shared\nbetween all of your builds.\nYou can add sets to this list by dragging them\nfrom the build's set list."] = "這是所有 Build 共用的\n物品組清單。\n你可以從 Build 的物品組清單\n拖曳物品組加入此清單。",
		["This is a list of items that will be shared between all of\nyour builds.\nYou can add items to this list by dragging them from\none of the other lists."] = "這是所有 Build 共用的\n物品清單。\n你可以從其他清單拖曳\n物品加入此清單。",
		["This is a special group created for the '"] = "這是為 '",
		["This is a special group created for the enemy explosion effect,\nwhich comes from the following sources:"] = "這是為敵人爆炸效果建立的特殊群組，\n來源如下:",
		["This is an older tree version, which may not be fully compatible with the current game version."] = "這是較舊的天賦樹版本，可能無法完全相容目前的遊戲版本。",
		["This is automatically enabled if you have a flask active,\nbut you can use this option to force it if necessary."] = "若你有藥劑生效中會自動啟用，\n但你可以用此選項強制啟用。",
		["This is automatically enabled if you have a tincture active,\nbut you can use this option to force it if necessary."] = "若你有萃取物生效中會自動啟用，\n但你可以用此選項強制啟用。",
		["This is for Blood Sap Tincture, but will limit you to only applying a single Bleed on the enemy"] = "此選項用於鮮血液萃取物，但會限制你只能對敵人施加單一流血",
		["This is for low tolerance, but will limit you to only applying poison a single time\n^8(Note that you can still apply multiple stacks via 'inflict additional poison' mods)^7"] = "此選項用於低容忍，但會限制你只能施加一次中毒\n^8（注意你仍可透過「額外施加中毒」詞綴施加多層）^7",
		["This is for party play, to export support character, it enables the exporting of auras, curses and modifiers to the enemy"] = "此功能用於組隊遊玩，匯出輔助角色時，可將光環、詛咒及對敵人的詞綴一併匯出",
		["This is the average roll of a Bleed affecting the enemy if you are constantly attacking"] = "這是你持續攻擊時，影響敵人的流血平均擲骰值",
		["This is the average roll of an ignite affecting the enemy if you are constantly attacking"] = "這是你持續攻擊時，影響敵人的點燃平均擲骰值",
		["This is the list of items that have been added to this build.\nYou can add items to this list by dragging them from\none of the other lists, or by clicking 'Add to build' when\nviewing an item."] = "這是已加入此配置的物品清單。\n你可以從其他清單拖曳物品到此處，\n或在檢視物品時點擊「加入配置」\n來新增。",
		["This item cannot have sockets"] = "此物品不能有插槽",
		["This Items Implicits Cannot Be Changed"] = "此物品的固定詞綴無法變更",
		["This list can be updated manually or by selecting the node you want to update via the search dropdown list and then moving the node weight sliders."] = "此清單可手動更新，或透過搜尋下拉選單選擇要更新的節點，再移動節點權重滑桿。",
		["This menu currently contains supported mod lines from tree nodes and item modifiers only.\n\nThis menu is not a representation of what PoB can parse, and this is only a limited list of mods. Additionally, some mods might be local to items and might not function in custom modifiers.\n\nA mod being supported does not necessarily mean that it will be included in calculations, and only means that the mod parser accepts it."] = "此選單目前只包含天賦點與物品詞綴中受支援的詞綴。\n\n此選單並不代表 PoB 能解析的全部內容，僅是有限的詞綴清單。此外，部分詞綴可能只作用於物品本身，在自訂詞綴中可能無效。\n\n詞綴受支援不代表一定會納入計算，僅表示詞綴解析器能接受它。",
		["This multiplies the damage of a given skill in pvp, for instance any with damage multiplier specific to pvp (from skill or support or item like sire of shards)"] = "乘上指定技能在 PvP 中的傷害，例如有 PvP 專屬傷害倍率的技能（來自技能、輔助或如破碎傳承者等物品）",
		["This node is granted by an item. Removing it will cause no changes"] = "此節點由物品賦予。移除不會造成任何變化",
		["This node is granted by an item. Removing it will give you:"] = "此節點由物品賦予。移除將使你:",
		["This node is only in the compared build"] = "此節點僅存在於比較的 Build",
		["This option allows you to override the default calculation for the number of Empty ^x7070FFBlue^7 Sockets.\nThe default calculation assumes enabled gems in skill socket groups fill the item in socket order disregarding gem colour.\nLeave blank for default calculation."] = "此選項可覆蓋空^x7070FF藍色^7插槽數量的預設計算。\n預設計算假設技能插槽組中已啟用的寶石依插槽順序填入物品，不考慮寶石顏色。\n留空則使用預設計算。",
		["This option allows you to override the default calculation for the number of Empty ^x70FF70Green^7 Sockets.\nThe default calculation assumes enabled gems in skill socket groups fill the item in socket order disregarding gem colour.\nLeave blank for default calculation."] = "此選項可覆蓋空^x70FF70綠色^7插槽數量的預設計算。\n預設計算假設技能插槽組中已啟用的寶石依插槽順序填入物品，不考慮寶石顏色。\n留空則使用預設計算。",
		["This option allows you to override the default calculation for the number of Empty ^xE05030Red^7 Sockets.\nThe default calculation assumes enabled gems in skill socket groups fill the item in socket order disregarding gem colour.\nLeave blank for default calculation."] = "此選項可覆蓋空^xE05030紅色^7插槽數量的預設計算。\n預設計算假設技能插槽組中已啟用的寶石依插槽順序填入物品，不考慮寶石顏色。\n留空則使用預設計算。",
		["This option allows you to override the default calculation for the number of Empty White Sockets.\nThe default calculation assumes enabled gems in skill socket groups fill the item in socket order disregarding gem colour.\nLeave blank for default calculation."] = "此選項可覆蓋空白色插槽數量的預設計算。\n預設計算假設技能插槽組中已啟用的寶石依插槽順序填入物品，不考慮寶石顏色。\n留空則使用預設計算。",
		["This option enables Manastorm's ^xADAA47Lightning ^7Damage Buff.\n(When you cast a Spell, Sacrifice all ^x7070FFMana ^7to gain Added Maximum ^xADAA47Lightning ^7Damage\nequal to 50% of Sacrificed ^x7070FFMana ^7for 4 seconds)"] = "此選項啟用魔能暴風的^xADAA47閃電^7傷害增益。\n（施放法術時，獻祭所有^x7070FF魔力^7以獲得附加最大^xADAA47閃電^7傷害，\n其值等於所獻祭 50% 的^x7070FF魔力^7，持續 4 秒）",
		["This option enables the Everlasting Sacrifice buff that grants +5% to all maximum resists."] = "此選項啟用永恆奉獻增益，所有最大抗性 +5%。",
		["This option is specific to '"] = "此選項專屬於 '",
		["This option is specific to Arborix."] = "此選項專用於阿布里斯。",
		["This option is specific to Augyre."] = "此選項專用於相星占卜。",
		["This option is specific to Oni-Goroshi."] = "此選項專用於西拉氣流殺。",
		["This option is specific to Vulconus."] = "此選項專用於祝融鍛冶。",
		["This option prevents EE from being reset by the hit damage of your main skill."] = "此選項可防止 EE 被主要技能的擊中傷害重置。",
		["This option sets the Movement Speed from Gamblesprint boots."] = "此選項設定豪賭鞋子提供的移動速度。",
		["This option sets whether an enemy is between you and your linked target."] = "此選項設定敵人是否位於你與連結目標之間。",
		["This option sets whether or not the enemy has hit you with ^x3F6DB3Cold Damage^7 in the last 4 seconds."] = "此選項設定敵人是否在過去 4 秒內以^x3F6DB3冰冷傷害^7擊中過你。",
		["This option sets whether or not the enemy has hit you with ^xADAA47Lightning Damage^7 in the last 4 seconds."] = "此選項設定敵人是否在過去 4 秒內以^xADAA47閃電傷害^7擊中過你。",
		["This option sets whether or not the enemy has hit you with ^xB97123Fire Damage^7 in the last 4 seconds."] = "此選項設定敵人是否在過去 4 秒內以^xB97123火焰傷害^7擊中過你。",
		["This overrides the default damage amount used to estimate your damage reduction from armour.\nThe default is 1.5 times the enemy's base damage, which is the same value\nused in-game to calculate the estimate shown on the character sheet."] = "此選項會覆蓋預設傷害值，用於估算你的護甲傷害減免。\n預設值為敵人基礎傷害的 1.5 倍，與遊戲中\n角色面板估算值所用的數值相同。",
		["This overrides the default enemy level used to estimate your hit and ^x33FF77evade ^7chance.\n\nThe default level for normal enemies and standard bosses is 83.\nTheir default level is capped by your character level.\n\nThe default level for pinnacle bosses is 84, and the default level for uber pinnacle bosses is 85.\nTheir default level is not capped by your character level."] = "此選項會覆蓋預設的敵人等級，用於估算你的命中與^x33FF77閃避 ^7機率。\n\n一般敵人與標準頭目的預設等級為 83。\n其預設等級受你的角色等級限制。\n\n巔峰頭目的預設等級為 84，終極巔峰頭目為 85。\n其預設等級不受你的角色等級限制。",
		["This part of the hit drains the following resources:"] = "此部分擊中將消耗以下資源:",
		["This sets the import button to append to the current party lists instead of replacing them (curses will still replace)"] = "讓匯入按鈕附加到目前的隊伍清單，而非取代 (詛咒仍會取代)",
		["This shows the advanced info like what stats each aura/curse etc are adding, as well as enables the ability to edit them without a re-export\nDo not edit any boxes unless you know what you are doing, use copy/paste or import instead"] = "顯示進階資訊，例如每個光環/詛咒等增加的數值，並可在不重新匯出的情況下編輯\n除非你清楚自己在做什麼，否則請勿編輯任何欄位，請改用複製/貼上或匯入",
		["This slider controls the weight of the following stat:"] = "此滑桿控制以下數值的權重:",
		["This socket group cannot be deleted as it is created by an equipped item."] = "此插槽群組由已裝備的物品建立，無法刪除。",
		["This will allow the skill to benefit from modifiers on the item that affect socketed gems."] = "這可讓技能受益於物品上影響已鑲嵌寶石的詞綴。",
		["This will enable the Acceleration Shrine buff.\n\\t50% increased Action Speed\n\\t80% increased Projectile Speed"] = "將啟用迅速神殿增益。\n\\t增加 50% 行動速度\n\\t增加 80% 投射物速度",
		["This will enable the Adrenaline buff, which grants:\n\\t100% increased Damage\n\\t25% increased Attack, Cast and Movement Speed\n\\t10% additional Physical Damage Reduction"] = "將啟用腎上腺素增益，提供:\n\\t增加 100% 傷害\n\\t增加 25% 攻擊、施放與移動速度\n\\t10% 額外物理傷害減免",
		["This will enable the Alchemist's Genius buff:\n20% increased Flask Charges gained\n10% increased effect of Flasks"] = "將啟用鍊金之材增益:\n增加 20% 獲得的藥劑充能\n增加 10% 藥劑效果",
		["This will enable the Blood Shrine of Bats buff.\n\\tCurse Enemies with Enfeeble on Hit\n\\tYou can apply an additional Curse"] = "將啟用蝠之鮮血神殿增益。\n\\t擊中時以衰弱詛咒敵人\n\\t你可以額外施加 1 個詛咒",
		["This will enable the Blood Shrine of Crows buff.\n\\t+50% to Chaos Resistance\n\\t10% of Elemental Damage taken as Chaos Damage\n\\t10% of Physical Damage taken as Chaos Damage"] = "將啟用鴉之鮮血神殿增益。\n\\t混沌抗性 +50%\n\\t承受的元素傷害 10% 轉為混沌傷害\n\\t承受的物理傷害 10% 轉為混沌傷害",
		["This will enable the Blood Shrine of Locusts buff.\n\\t+30% to Damage over Time Multiplier"] = "將啟用蝗之鮮血神殿增益。\n\\t+30% 持續傷害加成",
		["This will enable the Blood Shrine of Rats buff.\n\\tGain 30% of Elemental Damage as Extra Chaos Damage"] = "將啟用鼠之鮮血神殿增益。\n\\t獲得 30% 元素傷害的額外混沌傷害",
		["This will enable the Blood Shrine of Toads buff.\n\\tExplosive Toad has an additional 25% chance to Trigger when you kill an Enemy"] = "將啟用蟾之鮮血神殿增益。\n\\t擊殺敵人時，Explosive Toad 額外有 25% 機率觸發",
		["This will enable the Brutal Shrine buff.\n\\t50% increased Damage\n\\tKnocks Enemies Back on Hit\n\\t30% increased Stun Duration on Enemies"] = "將啟用猛擊神殿增益。\n\\t增加 50% 傷害\n\\t擊中時擊退敵人\n\\t增加 30% 對敵人的暈眩持續時間",
		["This will enable the Chaotic Might buff on your minions.\n(Grants 30% of Physical Damage as Extra ^xD02090Chaos ^7Damage)"] = "將對你的召喚物啟用混沌之力增益。\n（獲得 30% 物理傷害的額外^xD02090混沌 ^7傷害）",
		["This will enable the Chaotic Might buff.\n(Grants 30% of Physical Damage as Extra ^xD02090Chaos ^7Damage)"] = "將啟用混沌之力增益。\n（獲得 30% 物理傷害的額外^xD02090混沌 ^7傷害）",
		["This will enable the Diamond Shrine buff.\n\\tAll hits are Critical Strikes"] = "將啟用鑽石神殿增益。\n\\t所有擊中皆為暴擊",
		["This will enable the Divine Shrine buff.\n\\tCannot be Damaged"] = "將啟用聖潔神殿增益。\n\\t無法受到傷害",
		["This will enable the Divinity buff, which grants:\n\\t75% more Elemental Damage\n\\t25% less Elemental Damage taken"] = "將啟用神聖增益，提供:\n\\t75% 更多元素傷害\n\\t承受的元素傷害減少 25%",
		["This will enable the Echoing Shrine buff.\n\\t100% more Attack Speed\n\\t100% more Cast Speed\n\\tSkills Repeat an additional Time"] = "將啟用回響神殿增益。\n\\t100% 更多攻擊速度\n\\t100% 更多施放速度\n\\t技能額外重複 1 次",
		["This will enable the Fanaticism buff itself. (Grants 75% more cast speed, reduced skill cost, and increased area of effect)"] = "將啟用狂熱增益本身。（75% 更多施放速度、降低技能消耗並增加範圍效果）",
		["This will enable the Gloom Shrine buff.\n\\tGain 10% of Non-^xD02090Chaos ^7Damage as extra ^xD02090Chaos ^7Damage\n\\tEnemies you Kill have a 40% chance to Explode, dealing a quarter of their maximum ^xE05030Life ^7as ^xD02090Chaos ^7Damage"] = "將啟用漆黑神殿增益。\n\\t獲得 10% 非^xD02090混沌^7傷害的額外^xD02090混沌^7傷害\n\\t你擊殺的敵人有 40% 機率爆炸，造成其最大^xE05030生命^7四分之一的^xD02090混沌^7傷害",
		["This will enable the Greater Freezing Shrine buff.\n\\tGain 30% of Physical Damage as Extra ^x3F6DB3Cold ^7Damage\n\\tIce Novas happen around you"] = "將啟用高階霜寒神殿增益。\n\\t獲得 30% 物理傷害的額外^x3F6DB3冰冷^7傷害\n\\t你周圍會產生冰霜新星",
		["This will enable the Greater Shocking Shrine buff.\n\\tGain 30% of Physical Damage as Extra ^xADAA47Lightning ^7Damage\n\\tShock Novas happen around you"] = "將啟用高階雷霆神殿增益。\n\\t獲得 30% 物理傷害的額外^xADAA47閃電^7傷害\n\\t你周圍會產生感電新星",
		["This will enable the Greater Skeletal Shrine buff.\n\\tGain 30% of Physical Damage as Extra ^xD02090Chaos ^7Damage\n\\tSkeletons are summoned to you"] = "將啟用高階骷髏神殿增益。\n\\t獲得 30% 物理傷害的額外^xD02090混沌^7傷害\n\\t會為你召喚骷髏",
		["This will enable the Impenetrable Shrine buff.\n\\t100% increased Armour\n\\t100% increased ^x33FF77Evasion Rating^7\n\\t100% increased maximum ^x88FFFFEnergy Shield"] = "將啟用無畏神殿增益。\n\\t增加 100% 護甲\n\\t增加 100% ^x33FF77閃避值^7\n\\t增加 100% 最大^x88FFFF能量護盾",
		["This will enable the Lesser Acceleration Shrine buff.\n\\t10% increased Action Speed\n\\t30% increased Projectile Speed"] = "將啟用低階迅速神殿增益。\n\\t增加 10% 行動速度\n\\t增加 30% 投射物速度",
		["This will enable the Lesser Brutal Shrine buff.\n\\t20% increased Damage\n\\tKnocks Enemies Back on Hit\n\\t20% increased Stun Duration on Enemies"] = "將啟用低階猛擊神殿增益。\n\\t增加 20% 傷害\n\\t擊中時擊退敵人\n\\t增加 20% 對敵人的暈眩持續時間",
		["This will enable the Lesser Impenetrable Shrine buff.\n\\t50% increased Armour\n\\t50% increased ^x33FF77Evasion Rating^7\n\\t50% increased maximum ^x88FFFFEnergy Shield"] = "將啟用低階無畏神殿增益。\n\\t增加 50% 護甲\n\\t增加 50% ^x33FF77閃避值^7\n\\t增加 50% 最大^x88FFFF能量護盾",
		["This will enable the Lesser Massive Shrine buff.\n\\t10% increased Character Size\n\\t20% increased Area of Effect\n\\t20% increased maximum ^xE05030Life"] = "將啟用低階巨大神殿增益。\n\\t增加 10% 角色體型\n\\t增加 20% 範圍效果\n\\t增加 20% 最大^xE05030生命",
		["This will enable the Lesser Replenishing Shrine buff.\n\\t100% increased ^x7070FFMana ^7Regeneration Rate\n\\t3.3% of ^xE05030Life ^7Regenerated per second"] = "將啟用低階回復神殿增益。\n\\t增加 100% ^x7070FF魔力^7回復速度\n\\t每秒回復 3.3% ^xE05030生命^7",
		["This will enable the Lesser Resistance Shrine buff.\n\\t+25% to all Elemental Resistances\n\\t+2% to all maximum Resistances"] = "將啟用低階抗性神殿增益。\n\\t所有元素抗性 +25%\n\\t所有最大抗性 +2%",
		["This will enable the Massive Shrine buff.\n\\t30% increased Character Size\n\\t40% increased Area of Effect\n\\t40% increased maximum ^xE05030Life"] = "將啟用威猛神殿增益。\n\\t增加 30% 角色體型\n\\t增加 40% 範圍效果\n\\t增加 40% 最大^xE05030生命",
		["This will enable the Replenishing Shrine buff.\n\\t200% increased ^x7070FFMana ^7Regeneration Rate\n\\t6.7% of ^xE05030Life ^7Regenerated per second"] = "將啟用回復神殿增益。\n\\t增加 200% ^x7070FF魔力^7回復速度\n\\t每秒回復 6.7% ^xE05030生命^7",
		["This will enable the Resistance Shrine buff.\n\\t+50% to all Elemental Resistances\n\\t+10% to all maximum Resistances"] = "將啟用抗性神殿增益。\n\\t所有元素抗性 +50%\n\\t所有最大抗性 +10%",
		["This will enable the Resonating Shrine buff.\n\\t20% chance to gain a Power, Frenzy or Endurance Charge on Hit\n\\t60% chance to gain a Power, Frenzy or Endurance Charge on Kill\n\\t+1 to Maximum Power Charges\n\\t+1 to Maximum Frenzy Charges\n\\t+1 to Maximum Endurance Charges"] = "將啟用共鳴神殿增益。\n\\t擊中時 20% 機率獲得 1 顆暴擊球、狂怒球或耐力球\n\\t擊殺時 60% 機率獲得 1 顆暴擊球、狂怒球或耐力球\n\\t+1 最大暴擊球數量\n\\t+1 最大狂怒球數量\n\\t+1 最大耐力球數量",
		["This will enable the Sacrificial Zeal buff.\n(Grants 25% of the skill's mana cost as Physical Damage and causes you to take physical damage over time equal to a percentage of the skill's mana cost.)"] = "將啟用犧牲狂熱增益。\n（獲得技能魔力消耗 25% 的物理傷害，並使你承受相當於技能魔力消耗一定比例的物理持續傷害。）",
		["This will enable the Unholy Might buff on your minions.\n(Grants 100% of Physical Damage converted to ^xD02090Chaos ^7Damage)\n(25% chance to apply Wither on Hit)"] = "將對你的召喚物啟用不潔之力增益。\n（100% 物理傷害轉換為^xD02090混沌 ^7傷害）\n（擊中時 25% 機率施加凋零）",
		["This will enable the Unholy Might buff.\n(Grants 100% of Physical Damage converted to ^xD02090Chaos ^7Damage)\n(25% chance to apply Wither on Hit)"] = "將啟用不潔之力增益。\n（100% 物理傷害轉換為^xD02090混沌 ^7傷害）\n（擊中時 25% 機率施加凋零）",
		["This will override the number of Mines per throw"] = "將覆寫每次投擲的地雷數量",
		["This will override the number of Traps per throw"] = "將覆寫每次投擲的陷阱數量",
		["Thousands separator:"] = "千分位分隔符號:",
		["Three"] = "三",
		["Throwing rate:"] = "投擲速率:",
		["Throwing time:"] = "投擲時間:",
		["Time before death"] = "死亡前時間",
		["Time spent stationary"] = "靜止時間",
		["Time to Gain Max Seals"] = "達到最大封印時間",
		["Tincture Limit"] = "萃取物上限",
		["Tinctures"] = "萃取物",
		["Tip: After you finish importing a character, make sure you update the bandit choice,\nas it can only be imported by logging in above."] = "提示: 匯入角色後，請記得更新盜賊選擇，\n因為只有透過上方登入才能匯入。",
		["Tip: Hold Ctrl to hide this tooltip."] = "提示: 按住 Ctrl 可隱藏此提示框。",
		["Tip: Hold Shift or Ctrl to hide this tooltip."] = "提示: 按住 Shift 或 Ctrl 可隱藏此提示框。",
		["Tip: Hold Shift to display a tooltip for the granted skill"] = "提示: 按住 Shift 可顯示所授予技能的提示",
		["Tip: Press Ctrl+C to copy this node's text."] = "提示: 按 Ctrl+C 複製此節點的文字。",
		["Tip: Press Ctrl+D"] = "提示: 按 Ctrl+D",
		["Tip: Press Ctrl+D to disable the display of stat differences."] = "提示: 按 Ctrl+D 停用數值差異顯示。",
		["Tip: Press Ctrl+D to enable the display of stat differences."] = "提示: 按 Ctrl+D 啟用數值差異顯示。",
		["Tip: Right click this socket to go to the items page and choose the jewel for this socket."] = "提示: 對此插槽按右鍵，可前往物品頁面為此插槽選擇珠寶。",
		["Tip: Right click to edit the "] = "提示: 按右鍵編輯 ",
		["Tip: Right click to select a different effect"] = "提示: 按右鍵選擇其他效果",
		["Tip: To reach this node by a different path, hold Shift, then trace the path and click this node"] = "提示: 若要以不同路徑到達此節點，請按住 Shift，描繪路徑後點擊此節點",
		["Tip: You can drag items from the Items tab onto this dropdown to equip them onto the minion."] = "提示: 你可以從裝備分頁將物品拖曳到此下拉選單，讓召喚物裝備該物品。",
		["To be used with totems, minions, shot-gunning of projectiles (e.g., VD, magma-orbs),"] = "適用於圖騰、召喚物、投射物散射 (例如 VD、熔岩球)、",
