		["While ensnared, enemies take increased Projectile Damage from Attack Hits\nEnsnared enemies always count as moving, and have less movement speed while trying to break the snare."] = "被誘捕時，敵人增加承受攻擊擊中的投射物傷害\n被誘捕的敵人永遠視為移動中，且在掙脫時移動速度更低。",
