		["You may have too much cast speed or too little cooldown reduction to effectively use Vixen's Curse replacement"] = "你的施放速度可能過高或冷卻回復過低，無法有效使用雌狐的詛咒替換",
		["You must log in to use the search feature"] = "你必須登入才能使用搜尋功能",
		["You will automatically be considered to be Channeling if your main skill is a channelled skill,\nbut you can use this option to force it if necessary."] = "若你的主要技能為引導技能，將自動視為正在引導，\n但你可以用此選項強制啟用。",
		["You will automatically be considered to be Leeching if you have '^xE05030Life ^7Leech effects are not removed at Full ^xE05030Life^7',\nbut you can use this option to force it if necessary."] = "若你有「^xE05030生命^7偷取效果在^xE05030生命^7全滿時不會移除」，將自動視為正在偷取，\n但你可以用此選項強制啟用。",
		["You will automatically be considered to be on Full ^xE05030Life ^7if you have Chaos Inoculation,"] = "若你有異靈之體，會自動視為處於滿^xE05030生命^7，",
		["You will automatically be considered to be on Low ^x7070FFMana ^7if you have at least 50% ^x7070FFmana ^7reserved,\nbut you can use this option to force it if necessary."] = "若你至少保留了 50% ^x7070FF魔力^7，會自動視為處於低^x7070FF魔力^7，\n但必要時可用此選項強制設定。",
		["You will automatically be considered to be on Low ^x88FFFFEnergy Shield ^7if you have at least 50% ^x88FFFFES ^7reserved,\nbut you can use this option to force it if necessary."] = "若你至少保留了 50% ^x88FFFF護盾^7，會自動視為處於低^x88FFFF能量護盾^7，\n但必要時可用此選項強制設定。",
		["You will automatically be considered to be on Low ^xE05030Life ^7if you have at least "] = "會自動視為處於低^xE05030生命^7，若你至少保留了 ",
		["You will automatically be considered to have a Totem if your main skill is a Totem,\nbut you can use this option to force it if necessary."] = "若你的主要技能為圖騰，將自動視為擁有圖騰，\n但你可以用此選項強制啟用。",
		["You will automatically be considered to have Hit Recently if your main skill Hits and is self-cast,\nbut you can use this option to force it if necessary."] = "若你的主要技能會擊中且為自我施放，將自動視為近期有擊中，\n但你可以用此選項強制啟用。",
		["You will automatically be considered to have Summoned a Totem Recently if your main skill is a Totem,\nbut you can use this option to force it if necessary."] = "若你的主要技能為圖騰，將自動視為近期召喚過圖騰，\n但你可以用此選項強制啟用。",
		["You will automatically be considered to have unbroken ^xFFFF77Ward ^7if you have ^xAF6025Olroth's Resolve ^7active or\nan Iron Flask with enough Flask Charges gained on ^xFFFF77Ward ^7Break."] = "會自動視為擁有未破的^xFFFF77保護^7，若你啟用了^xAF6025奧爾羅斯的決心^7或\n擁有在^xFFFF77保護^7破裂時獲得足夠藥劑充能的鋼鐵藥劑。",
		["Your "] = "你的 ",
		["Your Absolution Skill Damage will not be scaled with Count setting.\nBy default it multiplies both minion count and skill hit count which leads to incorrect\nTotal DPS calculation since Absolution cannot inherently shotgun.\nDo not enable if you use Spell Totem support, Spell Cascade support or similar supports"] = "你的赦免技能傷害不會受數量設定影響。\n預設會同時乘上召喚物數量與技能擊中次數，導致\n總 DPS 計算錯誤，因為赦免本身無法霰彈。\n若使用法術圖騰輔助、秘能爆發輔助或類似輔助，請勿啟用",
		["Your Build"] = "你的建造",
		["Your Chaos Resistance"] = "你的混沌抗性",
		["your cloud provider"] = "你的雲端服務",
		["Your Dominating Blow Skill Damage will not be scaled with Count setting.\nBy default it multiplies both minion count and skill hit count which leads to incorrect\nTotal DPS calculation since Dominating Blow cannot inherently shotgun.\nDo not enable if you use Spell Totem support, Spell Cascade support or similar supports"] = "你的霸氣之擊技能傷害不會受數量設定影響。\n預設會同時乘上召喚物數量與技能擊中次數，導致\n總 DPS 計算錯誤，因為霸氣之擊本身無法霰彈。\n若使用法術圖騰輔助、秘能爆發輔助或類似輔助，請勿啟用",
		["Your Fire Resistance"] = "你的火焰抗性",
		["Your Holy Strike Skill Damage will not be scaled with Count setting.\nBy default it multiplies both minion count and skill hit count which leads to incorrect\nTotal DPS calculation since Holy Strike cannot inherently shotgun."] = "你的神聖打擊技能傷害不會受數量設定影響。\n預設會同時乘上召喚物數量與技能擊中次數，導致\n總 DPS 計算錯誤，因為神聖打擊本身無法霰彈。",
		["Your unreserved Life is below 1"] = "你的未保留生命低於 1",
